'use strict';
import $ from 'jquery';
import slick from 'slick-carousel';

export default class Carousel {
  constructor() {
  }

  init() {
      $(".hero-slider").slick({

          // normal options...
          slidesToShow: 1,
          slidesToScroll: 1,
          autoplay: true,
          autoplaySpeed: 2000,
          infinite: true,
          accessibility: true,
          speed: 1000,
  		  cssEase: 'linear',
		  arrows: false,
          dots: true,  
		  lazyLoad: 'progressive',

          // the magic
          responsive: [{

              breakpoint: 992,
              settings: {
                  slidesToShow: 1,
                  infinite: true
              }

          }, {

              breakpoint: 300,
              settings: "unslick" // destroys slick

          }]
      });
  }
}


